// SPDX-License-Identifier: GPL-2.0-or-later
// Generator for the Lian Li module device table.
// Usage: node scripts/openrgb/port-lianli-devices.mjs <openrgb-root> <commit>
// Reads LianLiControllerDetect.cpp and regenerates
// modules/lianli/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'LianLiController');
const detect = fs.readFileSync(path.join(family, 'LianLiControllerDetect.cpp'), 'utf8');
const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');
const constants = Object.fromEntries(
  [...(headerText + detect).matchAll(/#define\s+([A-Za-z][A-Za-z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
const n = (s) => {
  const t = s.trim();
  if (t in constants) return constants[t];
  if (/^0x[0-9A-Fa-f]+$/.test(t)) return Number.parseInt(t, 16);
  if (/^\d+$/.test(t)) return Number.parseInt(t, 10);
  throw new Error(`unresolved constant ${t}`);
};

// only the true USB-HID detectors are inventoried; the generic `REGISTER_DETECTOR`
// rows (Uni Hub legacy, Universal Screen, AL10) are non-HID USB transports.
const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR[A-Z_]*\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*([A-Za-z][A-Za-z0-9_]+)\s*,\s*([A-Za-z][A-Za-z0-9_]+)\s*(?:,\s*([^)]*)\))?/g,
)) {
  const vid = n(m[3]);
  const pid = n(m[4]);
  const args = (m[5] ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  let rec;
  if (args.length === 3) rec = { interface: n(args[0]) & 0xff, usagePage: n(args[1]), usage: n(args[2]) };
  else if (args.length === 1) rec = { interface: n(args[0]), usagePage: 65535, usage: 0 };
  else rec = { interface: 255, usagePage: 65535, usage: 0 };
  rows.push({ name: m[1], handler: m[2], vid, pid, ...rec });
}
if (rows.length !== 9) throw new Error(`expected 9 HID detector rows, got ${rows.length}`);

const out = path.join(process.cwd(), 'modules', 'lianli', 'src', 'devices_table.rs');
fs.mkdirSync(path.dirname(out), { recursive: true });
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-lianli-devices.mjs from OpenRGB ${commit}; do not edit.`,
  '// Only the USB-HID detector rows are inventoried; the generic REGISTER_DETECTOR',
  '// rows (Uni Hub legacy / Universal Screen / AL10) are non-HID USB transports and',
  '// blocked under freeRGB policy.',
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map((d) =>
    `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, usage_page: 0x${d.usagePage.toString(16)}, usage: ${d.usage}, },
`,
  ),
  '];',
  '',
];
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} Lian Li HID detectors`);